class Solution:
    def twoSum(self, nums: list[int], target: int) -> list[int]:
        # Write your solution here
        comps = {}
        for i in range(len(nums)):
            comp = target - nums[i]
            if comp in comps:
                return [comps[comp], i]
            comps[nums[i]] = i
        return []

