class Solution:
    def twoSum(self, numbers: list[int], target: int) -> list[int]:
        # Write your solution here
        lefta = 0
        righta = len(numbers)-1

        while lefta < righta:
            sum = numbers[lefta] + numbers[righta]
            if sum == target:
                return [lefta+1, righta+1]
            elif sum < target:
                lefta += 1
            else:
                righta -= 1
        return []

