class Solution:
    def threeSumClosest(self, nums: list[int], target: int) -> int:
        # Write your solution here
#         [-4, -1, 1, 2]
        res = nums[0] + nums[1] + nums[2]

        for i in range(len(nums)-2):
            lf = i + 1
            rt = len(nums)-1
            while lf < rt:
                s = nums[i] + nums[lf] + nums[rt]
                if s > target:
                    rt -= 1
                elif s < target:
                    lf += 1
                else:
                    return s
                if abs(s-target) < abs(res-target):
                    res = s
        return res
